    image: 'https://tsybcnnjylmvhsxzknug.supabase.co/storage/v1/object/sign/San%20Antonio%20Stucco/stucco-top-coat-san-antonio.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81N2ZkNDYwMC00NmYxLTQ0YWItYmZiYi1jODY3N2Y3YjM1MzgiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJTYW4gQW50b25pbyBTdHVjY28vc3R1Y2NvLXRvcC1jb2F0LXNhbi1hbnRvbmlvLmpwZyIsImlhdCI6MTc3NzU4MDczMiwiZXhwIjoxODA5MTE2NzMyfQ.c04kWDbJUcyX5-3_Ws_aeH9BuveIvzjTDX2zhlrM2xA',
